def state_abstraction(grid_world):
    grid = grid_world["grid"]
    rows, cols = len(grid), len(grid[0])
    visited = [[False for _ in range(cols)] for _ in range(rows)]

    def dfs(r, c, region):
        if 0 <= r < rows and 0 <= c < cols and not visited[r][c] and grid[r][c] != "X":
            region.append(grid_world["grid"][r][c])
            visited[r][c] = True
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                dfs(r + dr, c + dc, region)

    regions = []
    for r in range(rows):
        for c in range(cols):
            if not visited[r][c] and grid[r][c] != "X":
                region = []
                dfs(r, c, region)
                regions.append(region)

    return regions

